css:
.scalesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8edf7;
    background: radial-gradient(1200px 600px at 80% -10%, #1b2550 0%, #0c1230 55%, #070b22 100%);
    border-radius: 18px;
}

.scalesim-container * {
    box-sizing: border-box;
}

.scalesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #141d45 0%, #1c2a66 50%, #0d6a8f 120%);
    color: #f3f7ff;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid rgba(96, 165, 250, 0.25);
    box-shadow: 0 12px 34px rgba(8, 13, 40, 0.55);
}

.scalesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    background: linear-gradient(90deg, #7dd3fc 0%, #a5b4fc 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.scalesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #9fd5f5;
    background: rgba(125, 211, 252, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(125, 211, 252, 0.2);
}

.scalesim-subtitle {
    margin: 14px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdd8f0;
}

.scalesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b9c6ec;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.scalesim-period-counter #currentDay,
.scalesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #7dd3fc;
}

.scalesim-round-name {
    background: rgba(125, 211, 252, 0.14);
    color: #9fe0fb;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(125, 211, 252, 0.25);
}

.scalesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #fcd34d;
    background: rgba(252, 211, 77, 0.12);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(252, 211, 77, 0.25);
}

.scalesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.scalesim-status-card {
    background: rgba(20, 28, 64, 0.72);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(99, 130, 220, 0.22);
    box-shadow: 0 6px 18px rgba(6, 10, 34, 0.45);
    border-top: 4px solid #6366f1;
    backdrop-filter: blur(6px);
}

.scalesim-card-arr { border-top-color: #34d399; }
.scalesim-card-product { border-top-color: #38bdf8; }
.scalesim-card-customer { border-top-color: #a78bfa; }
.scalesim-card-runway { border-top-color: #fbbf24; }

.scalesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8ea0cc;
}

.scalesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eaf0ff;
}

.scalesim-card-arr .scalesim-value { color: #34d399; }
.scalesim-card-product .scalesim-value { color: #38bdf8; }
.scalesim-card-customer .scalesim-value { color: #a78bfa; }
.scalesim-card-runway .scalesim-value { color: #fbbf24; }

.scalesim-sublabel {
    font-size: 0.76rem;
    color: #8595c0;
    line-height: 1.35;
}

.scalesim-runway-danger { border-top-color: #ef4444; }
.scalesim-runway-danger .scalesim-value { color: #f87171; }

.scalesim-customer-low { border-top-color: #ef4444; }
.scalesim-customer-low .scalesim-value { color: #f87171; }

.scalesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(90deg, #101737 0%, #16214d 100%);
    color: #dce6ff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid rgba(99, 130, 220, 0.22);
}

.scalesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #7dd3fc;
}

.scalesim-budget-over #budgetDisplay {
    color: #f87171;
}

.scalesim-briefing {
    display: flex;
    gap: 14px;
    background: rgba(20, 28, 64, 0.7);
    border-left: 5px solid #38bdf8;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(6, 10, 34, 0.4);
}

.scalesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.scalesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #bfe4fb;
    margin-bottom: 6px;
}

.scalesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cdd8f0;
}

.scalesim-briefing-text strong { color: #34d399; }
.scalesim-briefing-text em { color: #fcd34d; font-style: italic; }

.scalesim-controls {
    background: rgba(16, 23, 55, 0.78);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(99, 130, 220, 0.22);
    box-shadow: 0 6px 18px rgba(6, 10, 34, 0.4);
}

.scalesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf0ff;
    border-bottom: 2px solid rgba(99, 130, 220, 0.25);
    padding-bottom: 8px;
}

.scalesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c2cdec;
    margin: 14px 0 6px;
}

.scalesim-container select,
.scalesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid rgba(99, 130, 220, 0.4);
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0e1538;
    color: #e8edf7;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.scalesim-container select:focus,
.scalesim-container input[type="number"]:focus {
    outline: none;
    border-color: #38bdf8;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
}

.scalesim-container select option {
    background-color: #0e1538;
    color: #e8edf7;
}

.scalesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #38bdf8;
}

.scalesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb3e4;
    margin-top: 4px;
}

.scalesim-range-readout span:last-child {
    color: #34d399;
    font-weight: 800;
}

.scalesim-hint {
    font-size: 0.8rem;
    color: #8595c0;
    margin-top: 4px;
    line-height: 1.4;
}

.scalesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.scalesim-container .btn-primary {
    background: linear-gradient(135deg, #2563eb 0%, #38bdf8 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #06122b;
    box-shadow: 0 8px 20px rgba(37, 99, 235, 0.35);
}

.scalesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.scalesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: rgba(99, 130, 220, 0.4);
    color: #9fb3e4;
    background: transparent;
}

.scalesim-coach {
    background: linear-gradient(135deg, #0d6a8f 0%, #1c2a66 100%);
    color: #eaf6ff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(125, 211, 252, 0.25);
    box-shadow: 0 8px 22px rgba(6, 10, 34, 0.45);
}

.scalesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9fe0fb;
    margin-bottom: 8px;
}

.scalesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.scalesim-coach-body strong { color: #fde68a; }
.scalesim-coach-body em { color: #fca5a5; font-style: italic; }

.scalesim-history,
.scalesim-chart {
    background: rgba(16, 23, 55, 0.78);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(99, 130, 220, 0.22);
    box-shadow: 0 6px 18px rgba(6, 10, 34, 0.4);
}

.scalesim-history h3,
.scalesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf0ff;
}

.scalesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdd8f0;
}

.scalesim-container table#usfHistoryTable th {
    background: rgba(56, 189, 248, 0.1);
    color: #bfe4fb;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(99, 130, 220, 0.3);
}

.scalesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(99, 130, 220, 0.14);
}

.scalesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(56, 189, 248, 0.04);
}

.scalesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .scalesim-container {
        padding: 14px;
    }
    .scalesim-header h1 {
        font-size: 1.7rem;
    }
    .scalesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .scalesim-value {
        font-size: 2rem;
    }
    .scalesim-clock {
        margin-left: 0;
    }
    .scalesim-period-counter {
        font-size: 0.88rem;
    }
    .scalesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .scalesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

js:
(function() {
    'use strict';

    class ScaleAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `El Dilema del Crecimiento Acelerado`;
            this.version = `1.1.0`;
            // Pre-round domainState snapshots so Undo can roll state back instead
            // of re-accumulating on resubmit (see initialize / calculateResults).
            this._snap = [];

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Rutalia S.L.).
            this.START_ARR = 1.2;            // €1,2M ARR
            this.START_PRODUCT = 30;         // uptime 99,2% / SLA 99,9%, deuda técnica → bajo
            this.START_CUSTOMER = 38;        // churn 2,5%, NRR 95%, concentración 55%
            this.START_RUNWAY = 45;          // ~45 meses con burn 120k€/mes
            this.CASH = 5.4;                 // €5,4M de caja (€5,0M nuevos + €0,4M previos)
            this.MIN_RUNWAY = 12;            // suelo de seguridad
            this.TARGET_PRODUCT = 65;        // umbral "listo para escalar"
            this.TARGET_CUSTOMER = 62;       // base de cliente sana
            this.WIN_ARR = 1.9;              // objetivo de ARR alcanzable por la vía sostenible (no por la agresiva, que quiebra)

            // Verdades del concepto.
            this.TRUE_READINESS = `data`;
            this.TRUE_BOTTLENECK = `concentration`;
            this.TRUE_SCENARIO = `consolidate`;
            this.TRUE_ALIGNMENT = `incentives`;
            this.TRUE_GOVERNANCE = `milestones`;
            this.TRUE_TRIGGER = `strict`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    arr: this.START_ARR,
                    product: this.START_PRODUCT,
                    customer: this.START_CUSTOMER,
                    runway: this.START_RUNWAY,
                    cashUsed: 0,
                    ranOut: false,
                    aggressiveTrap: false,
                    arrHistory: [this.START_ARR],
                    productHistory: [this.START_PRODUCT],
                    customerHistory: [this.START_CUSTOMER],
                    runwayHistory: [this.START_RUNWAY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Defaults NEUTROS/MEDIOS a propósito — un click-through NO debe ganar.
                state.decisions = {
                    readiness: `green`,
                    bottleneck: `market`,
                    diagnosis: 50,
                    scenario: `hybrid`,
                    productInvest: 200,
                    salesBudget: 95,
                    reversible: 50,
                    alignment: `personal`,
                    governance: `trust`,
                    concentration: 150,
                    relationship: 50,
                    trigger: `soft`,
                    metrics: `growth`,
                    brake: `round`,
                    discipline: 60
                };
            }
            // Undo support: the framework's Undo pops the last history row,
            // decrements currentPeriod and re-calls initialize() WITHOUT rolling
            // domainState back. If we hold more snapshots than history rows, an
            // Undo just happened -> restore the pre-round domainState so ARR /
            // product / customer / runway / history revert instead of drifting.
            const histLen = (state.history && state.history.length) || 0;
            if (this._snap && this._snap.length > histLen) {
                state.domainState = this._snap.pop();
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rd = document.getElementById(`readinessInput`);
                const bt = document.getElementById(`bottleneckInput`);
                const dg = document.getElementById(`diagnosisInput`);
                if (rd) decisions.readiness = rd.value;
                if (bt) decisions.bottleneck = bt.value;
                if (dg) decisions.diagnosis = parseInt(dg.value, 10);
                if (!Number.isFinite(decisions.diagnosis) || decisions.diagnosis < 0 || decisions.diagnosis > 100) {
                    warn(`warn_diagnosis_range`); return false;
                }
            } else if (round === 2) {
                const sc = document.getElementById(`scenarioInput`);
                const pi = document.getElementById(`productInvestInput`);
                const sb = document.getElementById(`salesBudgetInput`);
                const rv = document.getElementById(`reversibleInput`);
                if (sc) decisions.scenario = sc.value;
                if (pi) decisions.productInvest = parseFloat(pi.value);
                if (sb) decisions.salesBudget = parseFloat(sb.value);
                if (rv) decisions.reversible = parseInt(rv.value, 10);
                if (!Number.isFinite(decisions.productInvest) || decisions.productInvest < 0 || decisions.productInvest > 900) {
                    warn(`warn_product_range`); return false;
                }
                if (!Number.isFinite(decisions.salesBudget) || decisions.salesBudget < 40 || decisions.salesBudget > 150) {
                    warn(`warn_sales_range`); return false;
                }
                if (!Number.isFinite(decisions.reversible) || decisions.reversible < 0 || decisions.reversible > 100) {
                    warn(`warn_reversible_range`); return false;
                }
            } else if (round === 3) {
                const al = document.getElementById(`alignmentInput`);
                const gv = document.getElementById(`governanceInput`);
                const cn = document.getElementById(`concentrationInput`);
                const rl = document.getElementById(`relationshipInput`);
                if (al) decisions.alignment = al.value;
                if (gv) decisions.governance = gv.value;
                if (cn) decisions.concentration = parseFloat(cn.value);
                if (rl) decisions.relationship = parseInt(rl.value, 10);
                if (!Number.isFinite(decisions.concentration) || decisions.concentration < 0 || decisions.concentration > 600) {
                    warn(`warn_concentration_range`); return false;
                }
                if (!Number.isFinite(decisions.relationship) || decisions.relationship < 0 || decisions.relationship > 100) {
                    warn(`warn_relationship_range`); return false;
                }
            } else if (round === 4) {
                const tg = document.getElementById(`triggerInput`);
                const mt = document.getElementById(`metricsInput`);
                const bk = document.getElementById(`brakeInput`);
                const ds = document.getElementById(`disciplineInput`);
                if (tg) decisions.trigger = tg.value;
                if (mt) decisions.metrics = mt.value;
                if (bk) decisions.brake = bk.value;
                if (ds) decisions.discipline = parseInt(ds.value, 10);
                if (!Number.isFinite(decisions.discipline) || decisions.discipline < 0 || decisions.discipline > 100) {
                    warn(`warn_discipline_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            // Snapshot the pre-round domainState (serializable) so Undo can roll it
            // back in initialize() instead of re-accumulating on resubmit.
            this._snap.push(JSON.parse(JSON.stringify(ds)));
            const round = state.currentPeriod;

            // product = salud técnica/preparación; customer = NRR/churn/concentración;
            // arrDelta = crecimiento de ingresos; runwaySet = runway resultante; spend = caja.
            let productDelta = 0, customerDelta = 0, arrDelta = 0, spend = 0;
            let runwaySet = ds.runway;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ¿Está el producto listo para escalar? Auditar con datos, no con opiniones.
                if (d.readiness === this.TRUE_READINESS) {
                    productDelta += 5; customerDelta += 6; coachKey = `coach_r1_data`;
                } else if (d.readiness === `green`) {
                    productDelta -= 5; customerDelta -= 5; coachKey = `coach_r1_green`;
                } else {
                    productDelta -= 7; customerDelta -= 5; coachKey = `coach_r1_ignore`;
                }

                // Cuello de botella de mayor riesgo: la concentración de clientes (Error frecuente 4).
                if (d.bottleneck === this.TRUE_BOTTLENECK) {
                    customerDelta += 5; productDelta += 2;
                    if (d.readiness === this.TRUE_READINESS) coachKey = `coach_r1_sharp`;
                } else if (d.bottleneck === `market`) {
                    arrDelta += 0.02; customerDelta -= 3;
                } else if (d.bottleneck === `sales`) {
                    customerDelta -= 7; coachKey = `coach_r1_sales`;
                } else {
                    productDelta -= 7; customerDelta -= 9; coachKey = `coach_r1_none`;
                }

                // Disciplina de datos vs. tomar partido emocional (Error frecuente 1).
                if (d.diagnosis >= 60) { productDelta += 2; customerDelta += 2; }
                else if (d.diagnosis <= 25) { productDelta -= 5; customerDelta -= 6; coachKey = `coach_r1_lowdata`; }

                summaryKey = (d.readiness === this.TRUE_READINESS && d.bottleneck === this.TRUE_BOTTLENECK) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Dos escenarios: crecer rápido vs. consolidar. Distinguir riesgo reversible/irreversible.
                switch (d.scenario) {
                    case `consolidate`:
                        productDelta += 11; customerDelta += 7; arrDelta += 0.35; runwaySet = 24; coachKey = `coach_r2_consolidate`; break;
                    case `hybrid`:
                        productDelta += 3; customerDelta += 1; arrDelta += 0.30; runwaySet = 18; coachKey = `coach_r2_hybrid`; break;
                    case `aggressive`:
                        // Escalar distribución sobre producto frágil → churn dispara, runway colapsa (Error 3).
                        productDelta -= 11; customerDelta -= 15; arrDelta += 0.55; runwaySet = 12; ds.aggressiveTrap = true; coachKey = `coach_r2_aggressive`; break;
                }

                // Inversión en re-plataforma (~600k€). Producto sólido sostiene el escalado.
                spend += d.productInvest / 1000;
                if (d.productInvest >= 500) { productDelta += 10; customerDelta += 3; }
                else if (d.productInvest >= 250) { productDelta += 5; customerDelta += 1; }
                else { productDelta -= 5; coachKey = (d.scenario === `aggressive`) ? coachKey : `coach_r2_noproduct`; }

                // Presupuesto comercial: gasto sin bajar el churn = cubo agujereado (Error frecuente 2).
                spend += (d.salesBudget * 18) / 1000;
                if (d.salesBudget >= 130) {
                    arrDelta += 0.20;
                    if (ds.customer < this.TARGET_CUSTOMER) { customerDelta -= 9; coachKey = `coach_r2_overspend`; }
                } else if (d.salesBudget <= 80) {
                    arrDelta += 0.06; customerDelta += 3;
                } else {
                    arrDelta += 0.12;
                }

                // Riesgo reversible vs. irreversible.
                if (d.reversible >= 60) { customerDelta += 4; productDelta += 2; }
                else if (d.reversible <= 25) { customerDelta -= 6; coachKey = `coach_r2_irreversible`; }

                summaryKey = (d.scenario === `consolidate` && d.productInvest >= 500 && d.salesBudget <= 100) ? `sum_r2_good` : (d.scenario === `aggressive` ? `sum_r2_aggressive` : `sum_r2_weak`);
            } else if (round === 3) {
                // La sala del consejo: alinear intereses (Error frecuente 1; teoría de agencia).
                switch (d.alignment) {
                    case `incentives`: customerDelta += 4; productDelta += 3; coachKey = `coach_r3_incentives`; break;
                    case `founder`: productDelta += 2; customerDelta -= 5; coachKey = `coach_r3_founder`; break;
                    case `investor`: arrDelta += 0.08; customerDelta -= 9; productDelta -= 7; coachKey = `coach_r3_investor`; break;
                    case `personal`: customerDelta -= 5; coachKey = `coach_r3_personal`; break;
                }

                // Gobernanza: financiación por hitos es lo que ambos pueden firmar (Error frecuente 5).
                switch (d.governance) {
                    case `milestones`: productDelta += 7; customerDelta += 5; coachKey = (d.alignment === this.TRUE_ALIGNMENT) ? `coach_r3_aligned` : coachKey; break;
                    case `trust`: customerDelta -= 5; coachKey = `coach_r3_trust`; break;
                    case `veto`: productDelta -= 5; customerDelta -= 3; coachKey = `coach_r3_veto`; break;
                }

                // Diversificar y blindar las cuentas ancla (Error frecuente 4).
                spend += d.concentration / 1000;
                if (d.concentration >= 200) { customerDelta += 4; arrDelta += 0.08; }
                else if (d.concentration >= 100) { customerDelta += 2; arrDelta += 0.04; }
                else { customerDelta -= 8; coachKey = `coach_r3_concentration`; }

                // Salud de la relación a largo plazo.
                if (d.relationship >= 60) { customerDelta += 2; productDelta += 2; }
                else if (d.relationship <= 25) { customerDelta -= 5; }

                summaryKey = (d.alignment === this.TRUE_ALIGNMENT && d.governance === this.TRUE_GOVERNANCE) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Decisión y gobernanza: hitos, métricas y condiciones (Error frecuente 5).
                switch (d.trigger) {
                    case `strict`: productDelta += 6; customerDelta += 4; arrDelta += 0.30; coachKey = `coach_r4_strict`; break;
                    case `soft`: customerDelta -= 6; arrDelta += 0.10; coachKey = `coach_r4_soft`; break;
                    case `time`: productDelta -= 8; customerDelta -= 12; arrDelta += 0.30; coachKey = `coach_r4_time`; break;
                }

                // Cuadro de mando de gobierno mensual.
                switch (d.metrics) {
                    case `governance`: productDelta += 5; customerDelta += 4; break;
                    case `growth`: customerDelta -= 6; coachKey = `coach_r4_growthonly`; break;
                    case `none`: productDelta -= 7; customerDelta -= 9; coachKey = `coach_r4_nometrics`; break;
                }

                // Condición de freno (riesgo de caja / churn).
                switch (d.brake) {
                    case `churn`: customerDelta += 3; productDelta += 3; coachKey = (d.trigger === this.TRUE_TRIGGER && d.metrics === `governance`) ? `coach_r4_governed` : coachKey; break;
                    case `round`: runwaySet = Math.max(this.MIN_RUNWAY, ds.runway - 3); customerDelta -= 5; coachKey = `coach_r4_newround`; break;
                    case `push`: productDelta -= 11; customerDelta -= 13; arrDelta += 0.20; runwaySet = Math.max(6, ds.runway - 6); coachKey = `coach_r4_push`; break;
                }

                // Disciplina ante la presión por velocidad.
                customerDelta += Math.round((d.discipline - 60) / 12);

                summaryKey = (d.trigger === this.TRUE_TRIGGER && d.metrics === `governance` && d.brake === `churn`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Contabilidad de caja (M€), tope en la caja disponible.
            ds.cashUsed = Math.min(this.CASH, Math.round((ds.cashUsed + spend) * 100) / 100);

            // Aplicar deltas con tope 0–100.
            ds.product = Math.max(0, Math.min(100, ds.product + productDelta));
            ds.customer = Math.max(0, Math.min(100, ds.customer + customerDelta));
            ds.runway = Math.max(0, runwaySet);

            // El ARR crece, pero el churn (cliente bajo) drena el crecimiento — el cubo agujereado.
            const churnDrag = ds.customer < 50 ? (50 - ds.customer) / 100 * 0.4 : 0;
            const netArr = Math.max(0, arrDelta - churnDrag);
            ds.arr = Math.max(0, Math.round((ds.arr + netArr) * 100) / 100);

            if (ds.runway <= this.MIN_RUNWAY && round >= 2) {
                if (ds.runway < this.MIN_RUNWAY) ds.ranOut = true;
            }

            ds.arrHistory.push(Math.round(ds.arr * 100) / 100);
            ds.productHistory.push(Math.round(ds.product));
            ds.customerHistory.push(Math.round(ds.customer));
            ds.runwayHistory.push(Math.round(ds.runway));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // Advance the briefing / decision panel to the next round SYNCHRONOUSLY.
            // The framework increments currentPeriod right after this returns, so
            // the old deferred setTimeout read the already-incremented period and
            // revealed the round-after-next panel: after Round 1 it showed Round 3's
            // controls while validateDecisions still read the hidden Round 2 inputs,
            // so the player's visible choices were ignored. currentPeriod is still N
            // here, so N+1 is correct. Skip past the last round.
            if (state.currentPeriod < this.ROUNDS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            return {
                period: state.currentPeriod,
                arr: Math.round(ds.arr * 100) / 100,
                arrDelta: Math.round(netArr * 100) / 100,
                product: Math.round(ds.product),
                productDelta: Math.round(productDelta),
                customer: Math.round(ds.customer),
                customerDelta: Math.round(customerDelta),
                runway: Math.round(ds.runway),
                cashUsed: ds.cashUsed,
                aggressiveTrap: ds.aggressiveTrap,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

