                return Math.round(Number(v)) + ` ` + window.mySimulation.t(`unit_months`);
            });
            uiManager.bind(`budgetDisplay`, `domainState.cashUsed`, (v) => {
                const bar = document.querySelector(`.scalesim-budget-bar`);
                if (bar) bar.classList.toggle(`scalesim-budget-over`, Number(v) >= this.CASH - 0.001);
                return self._money(Number(v)) + ` / ` + self._money(self.CASH);
            });

            // Readout sliders.
            const bindReadout = (inputId, readoutId) => {
                const inp = document.getElementById(inputId);
                const out = document.getElementById(readoutId);
                if (inp && out) {
                    out.textContent = inp.value;
                    inp.addEventListener(`input`, function() { out.textContent = inp.value; });
                }
            };
            bindReadout(`diagnosisInput`, `diagnosisReadout`);
            bindReadout(`reversibleInput`, `reversibleReadout`);
            bindReadout(`relationshipInput`, `relationshipReadout`);
        }

        _money(value) {
            // Locale-aware EUR. ES: "2,40 M€" / "850.000 €". EN: "€2.40M" / "€850k".
            const lang = (window.mySimulation && window.mySimulation.language) || `es`;
            const v = Number(value) || 0;
            if (lang === `en`) {
                if (v >= 1) return `€` + v.toFixed(2) + `M`;
                return `€` + Math.round(v * 1000) + `k`;
            }
            // Español.
            if (v >= 1) return v.toFixed(2).replace(`.`, `,`) + ` M€`;
            return Math.round(v * 1000).toLocaleString(`de-DE`) + ` €`;
        }

