        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const arr = Math.round(ds.arr * 100) / 100;
            const product = Math.round(ds.product);
            const customer = Math.round(ds.customer);
            const runway = Math.round(ds.runway);

            const ready = product >= this.TARGET_PRODUCT && customer >= this.TARGET_CUSTOMER;
            const solvent = runway >= this.MIN_RUNWAY && !ds.ranOut;
            const grew = arr >= this.WIN_ARR;
            const composite = Math.round(
                Math.min(100, product) * 0.30 +
                Math.min(100, customer) * 0.30 +
                Math.min(100, runway / 24 * 100) * 0.20 +
                Math.min(100, arr / this.WIN_ARR * 100) * 0.20
            );

            let performance = `Escalado prematuro`;
            if (ready && solvent && grew && composite >= 72) performance = `Escalado sostenible`;
            else if (ready && solvent) performance = `Base sólida, crecimiento moderado`;
            else if (!solvent) performance = `Sin caja — quiebra de runway`;
            else if (grew && !ready) performance = `Crecimiento sobre arena`;

            const insights = [];
            if (ready && solvent && grew) insights.push(window.mySimulation.t(`insight_sustainable`));
            else if (!solvent) insights.push(window.mySimulation.t(`insight_runout`));
            else if (grew && !ready) insights.push(window.mySimulation.t(`insight_sand`));
            else if (!ready) insights.push(window.mySimulation.t(`insight_notready`));

            if (customer < 50) insights.push(window.mySimulation.t(`insight_churn`));
            if (product < 50) insights.push(window.mySimulation.t(`insight_product`));
            if (ds.aggressiveTrap) insights.push(window.mySimulation.t(`insight_aggressive`));
            if (ready && solvent && grew && composite >= 72) insights.push(window.mySimulation.t(`insight_milestones`));

            return {
                arr: arr,
                product: product,
                customer: customer,
                runway: runway,
                ready: ready,
                solvent: solvent,
                grew: grew,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.ranOut) return window.mySimulation.t(`hint_runout`);
            if (ds.aggressiveTrap && state.currentPeriod >= 2) return window.mySimulation.t(`hint_aggressive`);
            if (ds.customer < 35) return window.mySimulation.t(`hint_churn`);
            if (ds.product < 40 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_product`);
            if (state.currentPeriod >= 3 && (ds.product < this.TARGET_PRODUCT || ds.customer < this.TARGET_CUSTOMER)) return window.mySimulation.t(`hint_behind`);
            if (ds.product >= this.TARGET_PRODUCT && ds.customer >= this.TARGET_CUSTOMER && ds.runway >= this.MIN_RUNWAY) return window.mySimulation.t(`hint_strong`);
            return null;
        }

